### Tier 3: Production Hardening (30 minutes)

**Add Runtime Detection & Monitoring**

```java
// SECURE: Gadget class detection and monitoring
package com.example.security;

import org.springframework.stereotype.Component;
import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Component
public class DeserializationSecurityMonitor {

    private static final Logger log = LoggerFactory.getLogger(DeserializationSecurityMonitor.class);
    private final Counter deserializationAttempts;
    private final Counter gadgetDetections;

    private static final Set<String> GADGET_CLASSES = Set.of(
        "org.apache.commons.collections.functors.InvokerTransformer",
        "org.apache.commons.collections.functors.ChainedTransformer",
        "org.apache.commons.collections4.functors.InvokerTransformer",
        "org.codehaus.groovy.runtime.ConvertedClosure",
        "org.springframework.beans.factory.ObjectFactory",
        "com.sun.org.apache.xalan.internal.xsltc.trax.TemplatesImpl"
    );

    public DeserializationSecurityMonitor(MeterRegistry registry) {
        this.deserializationAttempts = Counter.builder("deserialization.attempts")
            .description("Deserialization attempts")
            .register(registry);

        this.gadgetDetections = Counter.builder("deserialization.gadget_detected")
            .description("Gadget chain detection attempts")
            .tag("severity", "critical")
            .register(registry);
    }

    public boolean isGadgetClass(String className) {
        boolean isGadget = GADGET_CLASSES.stream()
            .anyMatch(className::contains);

        if (isGadget) {
            log.error("SECURITY ALERT: Gadget class detected: {}", className);
            gadgetDetections.increment();
            // Send alert to security team
            sendSecurityAlert("Gadget Chain Deserialization Attempt", className);
        }

        return isGadget;
    }

    private void sendSecurityAlert(String title, String details) {
        // Implementation: Send to SIEM, email, PagerDuty, etc.
    }
}

